"""Generate docs/basemap1863/SOURCES-roads.md from the data files (counts, lengths, confidence tallies) and the source registry."""
import json, os, sys, collections, datetime
sys.path.insert(0, os.path.dirname(__file__))
from geomlib import *
from sources import SRC
MD = os.path.join(OUT, '..', '..', 'SOURCES-roads.md')

def load(n):
    p = os.path.join(OUT, n + '.geojson')
    return json.load(open(p))['features'] if os.path.exists(p) else []
def tally(fs):
    c = collections.Counter(f['properties']['confidence'] for f in fs); return ', '.join(f'{k} {v}' for k, v in sorted(c.items()))
def km(fs):
    return round(sum(length_m(shape(f['geometry'])) for f in fs if f.get('geometry') and f['geometry']['type'] in ('LineString', 'MultiLineString')) / 1000, 1)

def main():
    roads, rails, water, br, wf, fences = [load(n) for n in ('roads', 'railways', 'waterways', 'bridges', 'water_features', 'fences')]
    lanes = load('lanes')
    rm = json.load(open(os.path.join(OUT, 'modern-roads-remove.json')))
    clsc = collections.Counter(r['cls'] for r in rm); clsk = collections.defaultdict(float)
    for r in rm: clsk[r['cls']] += r['length_m_in_box'] / 1000
    ver = {}
    vd = os.path.join(OUT, 'verification')
    if os.path.isdir(vd):
        for fn in sorted(os.listdir(vd)):
            if fn.endswith('.json'): ver[fn] = json.load(open(os.path.join(vd, fn)))
    L = []
    A = L.append
    A('# Roads, railroads, bridges, waterways, fences and walls of July 1863: sources, methods, licences')
    A('')
    A('Owner: `docs/basemap1863/features/roads-rail-water/` and this file. Generated by `scripts/gen_sources_md.py` from the data files on %s; every number below comes from a script in `scripts/` or is marked as read, not measured.' % datetime.date.today().isoformat())
    A('')
    A('## 0. What this is, and what it is not')
    A('')
    A('**This is a RECONSTRUCTION.** No aerial photograph of the battlefield from 1863 exists. Every feature here is inferred from documents written or drawn later (the earliest large-scale survey of the ground is G. K. Warren\'s, made 1868-69, five years after the battle) and from the modern ground. It must be labelled as a reconstruction everywhere it is shown. It does not claim to be an exact or complete copy of the 1863 landscape: the claim it makes is limited to what each feature record states (sources, method, positional error in metres, confidence).')
    A('')
    A('Rules kept: nothing is drawn that no source supports; where a feature is unknown the record says `Unknown` and carries no geometry or an explicit flag, and the neutral surroundings are left alone; every feature has an id, its sources (title, page or sheet, URL, type), method, positional error and confidence. Source types: **A1** primary map or record made 1863-69 by a government survey or participant; **A2** later first-hand account or photograph; **B** secondary (NPS scholarship, compilations, modern open data). Confidence: **Documented** (a source names the feature and its place), **Estimated** (supported by class rules or modern geometry, place inferred), **Contested** (sources disagree), **Unknown**.')
    A('')
    A('## 1. Files')
    A('')
    A('| File (in `features/roads-rail-water/`) | What | Features | Confidence tally |')
    A('|---|---|---|---|')
    A(f'| `roads.geojson` (+ `.mercator.geojson`) | public roads and neighbourhood lanes of 1863 on their modern centreline | {len(roads)} ({km(roads)} km in the box) | {tally(roads)} |')
    A(f'| `lanes.geojson` | lanes and tracks, including lost ones, from the period map and NPS texts | {len(lanes)} | {tally(lanes) if lanes else "not yet written"} |')
    A(f'| `railways.geojson` | Gettysburg Railroad, the unfinished grade, post-1863 lines flagged `present_1863: false` | {len(rails)} | {tally(rails)} |')
    A(f'| `waterways.geojson` | NHD flowlines (streams) | {len(water)} ({km(water)} km) | {tally(water)} |')
    A(f'| `bridges.geojson` | crossings of 1863 roads with named streams: bridge or ford by class rule | {len(br)} | {tally(br)} |')
    A(f'| `water_features.geojson` | springs, mill dams, marsh | {len(wf)} | {tally(wf)} |')
    A(f'| `fences.geojson` | OSM-mapped fences and walls: CANDIDATES only (see 6) | {len(fences)} | {tally(fences)} |')
    A('| `modern-roads-remove.json` / `.csv` | every TIGER/Line road edge in the box classified: present in 1863 / not / undecided | %d edges | see section 7 |' % len(rm))
    A('| `verification/` | the verification passes (section 9) | | |')
    A('| `scripts/` | every script that produced the files (re-runnable; caches are in `tmp/b1863/roads/`, not committed) | | |')
    A('')
    A('Coordinates: GeoJSON in EPSG:4326 (WGS 84, lng/lat) and a Web Mercator (EPSG:3857, metres) copy of each file. Box: the Battle Studio data box (`docs/pitch/anim2/basemap/plan.json`: west -77.3178, south 39.77, east -77.18, north 39.8594) plus the plan\'s 1,200 m margin (west %.4f, south %.4f, east %.4f, north %.4f).' % (XW, XS, XE, XN))
    A('')
    A('## 2. Licence and attribution table')
    A('')
    A('| Source | Used for | Licence | Attribution |')
    A('|---|---|---|---|')
    A('| U.S. Census Bureau, TIGER/Line 2023 Roads, Adams County PA (`tl_2023_42001_roads`) | modern road centrelines; the classification table | public domain | "Source: U.S. Census Bureau, TIGER/Line Shapefiles" |')
    A('| USGS National Hydrography Dataset (high resolution), The National Map hydro service | stream flowlines | public domain (USGS) | "Data: USGS National Hydrography Dataset" |')
    A('| National Park Service documents hosted at npshistory.com and irma.nps.gov: Cultural Landscapes Inventories (Gettysburg Landscape 2000/2004; First Day 2021; Emmitsburg Road Ridge 2024; Pickett\'s Charge 2024; Little Round Top 2020), Cultural Landscape Reports (1st Corps 2021; Record of Treatment 2018; Little Round Top 2012), Treatment Philosophy: The 1863 Landscape (2004), Historical Base Map documentation (1958) | evidence for what existed, with page references | works of the U.S. Government: public domain (the npshistory.com host is a third-party mirror; the NPS IRMA links are the originals where given) | "National Park Service, Gettysburg NMP" |')
    A('| Library of Congress Geography and Map Division: Map of the battle field of Gettysburg, 1876/1879 (Bachelder, topography from Warren 1868-69), item 99447491, sheets cw0325000a-c; item 99448794 (cw0353500) | period road, lane, fence, stream and railroad drawing: read for the map checks (the images are not republished here) | public domain; LOC states no known restrictions | "Library of Congress, Geography and Map Division" |')
    A('| OpenStreetMap contributors (Overpass API extract, 2026-10-19) | rail lines, abandoned Round Top Branch, mapped fences/walls (candidates), bridge ways, building names | ODbL 1.0: attribution "(c) OpenStreetMap contributors" and share-alike for the database derived from it | The files that contain OSM geometry say so in `method` (rail and fence files) |')
    A('| Wikipedia (CC BY-SA 4.0), AARoads wiki (copyright AARoads) | facts only: Wheatfield Road article (road description); US 15 Gettysburg bypass opening date 28 June 1963 | facts cited, no text copied | cited in the removal table |')
    A('')
    A('Not used, on purpose: Google Earth, Google Maps, Bing, Maxar, Mapbox imagery (their terms forbid it). No source was scraped through a block; the Overpass server answered 502 for part of the session and was retried politely (60-120 s apart). Downloads: TIGER zip 1.08 MB; the NPS PDFs listed above; LOC IIIF JPEG renderings of three Bachelder sheets and one further LOC map (kept in `tmp/`, not committed).')
    A('')
    A('## 3. How each class was built')
    A('')
    A('1. **Public roads (ten roads of the borough, county and township roads)** - the road is catalogued from NPS statements (the ten-road list, county-road list, individual road histories) and the 1876 Bachelder/Warren drawing; its geometry is the centreline of the TIGER/Line 2023 edge on that route. Rationale: the 1863 pikes and county roads were re-surfaced in place, so the modern centreline is within a few metres of the modern photograph and very likely within the width of the 1863 road, EXCEPT where a later realignment is documented (Taneytown and Emmitsburg Road widenings and fence setbacks, 1930s, `NPS-CLI-EMM` p90; United States Avenue realigned 1935-43). Positional error stated per road. Confidence is `Estimated` until the period-map check (section 9, passes 5-7) confirms the same line on the map.')
    A('2. **Lost lanes and traces** - from the period map and NPS texts; written to `lanes.geojson` only with a source for each (section 5).')
    A('3. **Railroads** - the Gettysburg (Hanover Junction, Hanover and Gettysburg) Railroad reached the borough in 1858 (NPS: tracks had reached the town from the east; the westward extension was graded but not laid). The modern CSX Hanover Subdivision is on the same corridor; its geometry is used with error 30-40 m, confidence Estimated. The Round Top Branch (1884-1942) and the Gettysburg Electric Railway (1893-1916) are post-1863 and flagged `present_1863: false`.')
    A('4. **Streams** - NHD flowlines (modern course), with the NPS caveat that courses have changed over 140 years; ditches/artificial paths through modern ponds are flagged `Unknown`. Modern ponds (NHD waterbodies, %d in the box) are NOT 1863 features: NPS names only two ponds on the 1863 battlefield, McPherson\'s (still exists) and Biesecker\'s (removed); neither is located by a source read.' % 154)
    A('5. **Bridges and fords** - by class rule from NPS (bridges on the turnpikes and state roads; fords everywhere else), at the TIGER x NHD crossing; not individually documented, so `Estimated`, error 30 m.')
    A('6. **Fences and walls** - the NPS rebuilds fences on documented 1863 lines in the 1863 styles (`NPS-TREAT-2004` p69), and OSM mappers traced those fences. A mapped fence is a candidate for an 1863 line, not evidence: some park fences stand in non-historic positions (CLI First Day p58, p61-62 give examples). All %d are `confidence: Unknown`, `present_1863: null`, until each is checked against the Warren/Bachelder fence drawing.' % len(fences))
    A('')
    A('## 4. Modern roads that did not exist in 1863 (summary; the full table with TIGER ids is `modern-roads-remove.csv`)')
    A('')
    A('| Class | TIGER edges | km in box | Basis |')
    A('|---|---|---|---|')
    names = {'ROAD_1863_SAME_LINE': 'catalogued 1863 road (same line)', 'DUPLICATE_ROUTE_DESIGNATION': 'repeat of an 1863 road under a route number', 'ROAD_1863_CANDIDATE': 'candidate 1863 road, existence not yet established',
             'EXPRESSWAY_US15': 'US 15 Gettysburg bypass (opened 28 June 1963)', 'RAMP_OR_TURN_LANE': 'ramp / turn lane of the modern highway', 'NPS_MEMORIAL_AVENUE': 'NPS memorial avenue (1882-1920)',
             'PRIVATE_DRIVE': 'private road or driveway (TIGER S1740)', 'PARKING_LOT_ROAD': 'parking-lot road', 'WALKING_PATH': 'walking path', 'ALLEY': 'alley (undecided)', 'TOWN_STREET_UNDECIDED': 'street inside the borough footprint (undecided)',
             'RURAL_ROAD_UNDECIDED': 'long rural road, 1863 existence not confirmed (undecided)', 'POST_1863_STREET_OR_DRIVE': 'short street, court, drive, lane of the modern pattern'}
    for k, v in sorted(clsc.items(), key=lambda x: -clsk[x[0]]):
        A(f'| {k} | {v} | {clsk[k]:.1f} | {names.get(k, k)} |')
    A('')
    A('`present_1863` is `true` only for the catalogued roads; `false` for classes with a source; `null` for undecided ones. Undecided edges are resolved by the period-map checks and recorded in `removal_overrides.json` when decided.')
    A('')
    A('## 5. Lanes: documented lost and altered lanes')
    A('')
    A('See `lanes.geojson` and the `lanes` notes in the verification files. The lanes named by NPS for 1863 (Trostle-Weikert-Swisher, Granite Schoolhouse, McAllister Mill, Wills-McPherson-Sheads; McPherson, Slyder, Culp, Forney, Long Lane, McMillan-McDannell, Spangler, Codori, Klingel, Bushman) are listed in `lanes_inventory.json` with their NPS sources and status; geometry exists only for those traced from the period map or a mapped NPS lane.' if not lanes else 'See `lanes.geojson`.')
    A('')
    A('## 6. Accuracy (measured) and what is uncertain')
    A('')
    A('The measured figures are in `verification/` (passes 5-7) and are repeated in the README of the folder. Open items are listed at the end of that README. Nothing in this file says the reconstruction is exact.')
    A('')
    A('## 7. Verification log')
    A('')
    for fn, d in ver.items():
        A('- `%s`: %s' % (fn, json.dumps(d)[:300].replace('|', '/')))
    A('')
    open(MD, 'w', encoding='utf8').write('\n'.join(L))
    print('wrote', MD, len(L), 'lines')

if __name__ == '__main__':
    main()
